using CouponBook.Business.Redemptions;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace CouponBook.Api.Controllers;
public record RedeemRequest(string Code,decimal? BillAmount);
[ApiController][Route("api/provider/redemptions")][Authorize(Roles="Provider")]public class RedemptionsController:ControllerBase{private readonly IRedemptionService _r;public RedemptionsController(IRedemptionService r)=>_r=r;private int U=>int.Parse(User.FindFirst("sub")!.Value);[HttpGet("validate/{code}")]public async Task<IActionResult>Validate(string code){var x=await _r.ValidateAsync(U,code);return x.Succeeded?Ok(x.Value):BadRequest(new{code=x.ErrorCode});}[HttpPost("confirm")]public async Task<IActionResult>Confirm(RedeemRequest q){var x=await _r.ConfirmAsync(U,q.Code,q.BillAmount);return x.Succeeded?Ok(x.Value):BadRequest(new{code=x.ErrorCode});}}
